/// Everything the user-detail page renders, in one request.
class AdminUserProfile {
  const AdminUserProfile({
    required this.activeDays,
    required this.libraries,
    required this.msPlayed,
    required this.playlists,
    required this.recentAudit,
    required this.sessions,
    required this.user,
    this.badges,
    this.firstPlayMs,
    this.lastPlayMs,
    this.planGrant,
  });

  /// Distinct days with any listening at all — a better read of "is this account used" than a
  /// play count, which one long weekend can inflate.
  final int activeDays;
  final List<AdminUserLibrary> libraries;

  /// Total listening time, milliseconds. From the daily rollup, never the fact table.
  final int msPlayed;
  final int playlists;

  /// This account's recent history as a TARGET of admin action, not as an actor.
  final List<AuditEntry> recentAudit;
  final List<AdminSession> sessions;
  final AdminUserDetail user;

  /// Every badge this account carries, assignable or not.
  ///
  /// The full list rather than just the two an admin can change, because the derived ones are
  /// context an admin needs: whether someone is already a paying supporter changes whether comping
  /// them a staff role is generous or redundant. The editor renders the assignable pair and shows
  /// the rest as read-only.
  final List<ProfileBadge>? badges;
  final int? firstPlayMs;
  final int? lastPlayMs;
  final AdminPlanGrantView? planGrant;

  factory AdminUserProfile.fromJson(Map<String, Object?> json) =>
      AdminUserProfile(
        activeDays: asInt(json['active_days']),
        libraries: asList(
          json['libraries'],
        ).map((e) => AdminUserLibrary.fromJson(asObject(e))).toList(),
        msPlayed: asInt(json['ms_played']),
        playlists: asInt(json['playlists']),
        recentAudit: asList(
          json['recent_audit'],
        ).map((e) => AuditEntry.fromJson(asObject(e))).toList(),
        sessions: asList(
          json['sessions'],
        ).map((e) => AdminSession.fromJson(asObject(e))).toList(),
        user: AdminUserDetail.fromJson(asObject(json['user'])),
        badges: asListOrNull(
          json['badges'],
        )?.map((e) => ProfileBadge.fromJson(asObject(e))).toList(),
        firstPlayMs: asIntOrNull(json['first_play_ms']),
        lastPlayMs: asIntOrNull(json['last_play_ms']),
        planGrant: json['plan_grant'] == null
            ? null
            : AdminPlanGrantView.fromJson(asObject(json['plan_grant'])),
      );

  Map<String, Object?> toJson() => {
    'active_days': activeDays,
    'libraries': libraries.map((e) => e.toJson()).toList(),
    'ms_played': msPlayed,
    'playlists': playlists,
    'recent_audit': recentAudit.map((e) => e.toJson()).toList(),
    'sessions': sessions.map((e) => e.toJson()).toList(),
    'user': user.toJson(),
    if (badges != null) 'badges': badges!.map((e) => e.toJson()).toList(),
    if (firstPlayMs != null) 'first_play_ms': firstPlayMs,
    if (lastPlayMs != null) 'last_play_ms': lastPlayMs,
    if (planGrant != null) 'plan_grant': planGrant!.toJson(),
  };
}

