    this.artistImageUrl,
    this.artistMbid,
    this.artistName,
    this.coverUrl,
  });

  /// The album's editions, in display order (Standard first).
  final List<AlbumEdition> editions;

  /// True while the recording listing is still being fetched.
  final bool refreshing;

  /// The release-group MBID this breakdown is for.
  final String rgMbid;
  final String title;

  /// The album artist's image, for the breadcrumb avatar.
  final String? artistImageUrl;

  /// The album artist's MusicBrainz id, for linking.
  final String? artistMbid;

  /// The album artist's display name, for the breadcrumb trail and linking back to the artist.
  final String? artistName;
  final String? coverUrl;

  factory AlbumTrackCoverage.fromJson(Map<String, Object?> json) =>
      AlbumTrackCoverage(
        editions: asList(
          json['editions'],
        ).map((e) => AlbumEdition.fromJson(asObject(e))).toList(),
        refreshing: asBool(json['refreshing']),
        rgMbid: asString(json['rg_mbid']),
        title: asString(json['title']),
        artistImageUrl: asStringOrNull(json['artist_image_url']),
        artistMbid: asStringOrNull(json['artist_mbid']),
        artistName: asStringOrNull(json['artist_name']),
        coverUrl: asStringOrNull(json['cover_url']),
      );

  Map<String, Object?> toJson() => {
    'editions': editions.map((e) => e.toJson()).toList(),
    'refreshing': refreshing,
    'rg_mbid': rgMbid,
    'title': title,
    if (artistImageUrl != null) 'artist_image_url': artistImageUrl,
    if (artistMbid != null) 'artist_mbid': artistMbid,
    if (artistName != null) 'artist_name': artistName,
    if (coverUrl != null) 'cover_url': coverUrl,
  };
}

