/// Owned-vs-missing breakdown for one artist the user (partially) owns.
class ArtistCoverage {
  const ArtistCoverage({
    required this.artistId,
    required this.coveragePct,
    required this.missing,
    required this.name,
    required this.owned,
    required this.refreshing,
    this.artistMbid,
  });

  /// The owned-catalog artist id (for navigation).
  final String artistId;

  /// Album-level coverage for this artist (0..100).
  final double coveragePct;

  /// Release-groups in the discography the user does NOT own.
  final List<ExtReleaseGroup> missing;
  final String name;

  /// Albums the user owns (from their libraries).
  final List<BrowseAlbum> owned;

  /// True when the discography is still being fetched (missing list is provisional). The client
  /// should refetch on the next realtime catalog nudge.
  final bool refreshing;

  /// The artist's MusicBrainz id, if known (needed to diff the discography).
  final String? artistMbid;

  factory ArtistCoverage.fromJson(Map<String, Object?> json) => ArtistCoverage(
    artistId: asString(json['artist_id']),
    coveragePct: asDouble(json['coverage_pct']),
    missing: asList(
      json['missing'],
    ).map((e) => ExtReleaseGroup.fromJson(asObject(e))).toList(),
    name: asString(json['name']),
    owned: asList(
      json['owned'],
    ).map((e) => BrowseAlbum.fromJson(asObject(e))).toList(),
    refreshing: asBool(json['refreshing']),
    artistMbid: asStringOrNull(json['artist_mbid']),
  );

  Map<String, Object?> toJson() => {
    'artist_id': artistId,
    'coverage_pct': coveragePct,
    'missing': missing.map((e) => e.toJson()).toList(),
    'name': name,
    'owned': owned.map((e) => e.toJson()).toList(),
    'refreshing': refreshing,
    if (artistMbid != null) 'artist_mbid': artistMbid,
  };
}

/// Full artist page payload.
class ArtistDetail {
  const ArtistDetail({
    required this.albums,
    required this.id,
    required this.name,
    required this.topTracks,
    this.area,
    this.artistType,
    this.bannerUrl,
    this.bannerWidth,
    this.beginArea,
    this.beginDate,
    this.bio,
    this.endDate,
    this.ended,
    this.genres,
    this.imageUrl,
    this.labels,
    this.links,
    this.liveTrackCount,
    this.mbid,
    this.monthlyListeners,
    this.related,
  });

  final List<BrowseAlbum> albums;
  final String id;
  final String name;
  final List<BrowseTrack> topTracks;

  /// Where the artist is from (associated area / country region name).
  final String? area;

  /// MB type: `"Person"`, `"Group"`, `"Orchestra"`, …
  final String? artistType;
  final String? bannerUrl;

  /// Intrinsic pixel width of `banner_url`'s image, when the Hub knows it.
  ///
  /// The banner is rendered edge-to-edge with a `srcSet`, and a `Nw` descriptor is a PROMISE about
  /// the candidate's real width — the browser picks on that number without ever measuring the
  /// file. Banner art comes from fanart.tv at whatever size the uploader chose, so a hard-coded
  /// descriptor is a guess, and guessing high makes the browser choose a small file for a wide
  /// slot and upscale it. Absent means "unknown": emit no `srcSet` rather than an invented one.
  final int? bannerWidth;

  /// Formation place / birthplace.
  final String? beginArea;

  /// Career/life start, raw MB partial date (`YYYY` | `YYYY-MM` | `YYYY-MM-DD`).
  final String? beginDate;
  final String? bio;

  /// Career/life end (disbanded / deceased), if any.
  final String? endDate;

  /// True when the artist's life-span has ended (group disbanded / person deceased).
  final bool? ended;
  final List<String>? genres;
  final String? imageUrl;

  /// Labels this artist has released on, with the year span (derived from their albums).
  final List<ArtistLabel>? labels;

  /// External links (official site, streaming, social) from MusicBrainz, curated to the platforms
  /// worth surfacing. Rendered as icon links on the artist page.
  final List<ArtistLink>? links;

  /// Owned live material for this artist (live-version album tracks + scattered "(Live)" bonus
  /// variants), so the client can offer the dynamic Live album even when no live album exists.
  final int? liveTrackCount;

  /// MusicBrainz id, when known. Lets a menu link straight to the artist's Manager discography
  /// page instead of dropping the user into a name search. Mirrors `BrowseArtist::mbid`.
  final String? mbid;

  /// Distinct listeners across the Hub in the last ~30 days.
  final int? monthlyListeners;

  /// Linked artists such as aliases, side-projects, or bands (see [`ArtistRelation`]).
  final List<ArtistRelation>? related;

  factory ArtistDetail.fromJson(Map<String, Object?> json) => ArtistDetail(
    albums: asList(
      json['albums'],
    ).map((e) => BrowseAlbum.fromJson(asObject(e))).toList(),
    id: asString(json['id']),
    name: asString(json['name']),
    topTracks: asList(
      json['top_tracks'],
    ).map((e) => BrowseTrack.fromJson(asObject(e))).toList(),
    area: asStringOrNull(json['area']),
    artistType: asStringOrNull(json['artist_type']),
    bannerUrl: asStringOrNull(json['banner_url']),
    bannerWidth: asIntOrNull(json['banner_width']),
    beginArea: asStringOrNull(json['begin_area']),
    beginDate: asStringOrNull(json['begin_date']),
    bio: asStringOrNull(json['bio']),
    endDate: asStringOrNull(json['end_date']),
    ended: asBoolOrNull(json['ended']),
    genres: asListOrNull(json['genres'])?.map((e) => asString(e)).toList(),
    imageUrl: asStringOrNull(json['image_url']),
    labels: asListOrNull(
      json['labels'],
    )?.map((e) => ArtistLabel.fromJson(asObject(e))).toList(),
    links: asListOrNull(
      json['links'],
    )?.map((e) => ArtistLink.fromJson(asObject(e))).toList(),
    liveTrackCount: asIntOrNull(json['live_track_count']),
    mbid: asStringOrNull(json['mbid']),
    monthlyListeners: asIntOrNull(json['monthly_listeners']),
    related: asListOrNull(
      json['related'],
    )?.map((e) => ArtistRelation.fromJson(asObject(e))).toList(),
  );

  Map<String, Object?> toJson() => {
    'albums': albums.map((e) => e.toJson()).toList(),
    'id': id,
    'name': name,
    'top_tracks': topTracks.map((e) => e.toJson()).toList(),
    if (area != null) 'area': area,
    if (artistType != null) 'artist_type': artistType,
    if (bannerUrl != null) 'banner_url': bannerUrl,
    if (bannerWidth != null) 'banner_width': bannerWidth,
    if (beginArea != null) 'begin_area': beginArea,
    if (beginDate != null) 'begin_date': beginDate,
    if (bio != null) 'bio': bio,
    if (endDate != null) 'end_date': endDate,
    if (ended != null) 'ended': ended,
    if (genres != null) 'genres': genres,
    if (imageUrl != null) 'image_url': imageUrl,
    if (labels != null) 'labels': labels!.map((e) => e.toJson()).toList(),
    if (links != null) 'links': links!.map((e) => e.toJson()).toList(),
    if (liveTrackCount != null) 'live_track_count': liveTrackCount,
    if (mbid != null) 'mbid': mbid,
    if (monthlyListeners != null) 'monthly_listeners': monthlyListeners,
    if (related != null) 'related': related!.map((e) => e.toJson()).toList(),
  };
}

/// A label an artist has released on, with the span of years (for the artist-page label history).
class ArtistLabel {
  const ArtistLabel({
    required this.albumCount,
    required this.id,
    required this.name,
    this.firstYear,
    this.lastYear,
  });

  final int albumCount;
  final String id;
