        sampleRateHz: asInt(json['sample_rate_hz']),
        spatial: asBool(json['spatial']),
        gainDb: asDoubleOrNull(json['gain_db']),
        peak: asDoubleOrNull(json['peak']),
      );

  Map<String, Object?> toJson() => {
    'bit_depth': bitDepth,
    'channels': channels,
    'codec': codec,
    'lossless': lossless,
    'sample_rate_hz': sampleRateHz,
    'spatial': spatial,
    if (gainDb != null) 'gain_db': gainDb,
    if (peak != null) 'peak': peak,
  };
}

