/// One entry in the append-only privileged-action log.
///
/// `target_type` and `target_label` are what make an entry legible. A bare `target_id` is a UUID
/// with no way to resolve it — worse, `delete_user` destroys the row it points at, so after the fact
/// there is nothing left to resolve it *against*. The label is therefore captured at write time and
/// denormalized here on purpose; it is a record of what the target was called when the thing
/// happened, not a live lookup.
class AuditEntry {
  const AuditEntry({
    required this.action,
    required this.backfilled,
    required this.category,
    required this.createdAtMs,
    required this.id,
    this.actorHandle,
    this.actorId,
    this.after,
    this.before,
    this.detail,
    this.targetId,
    this.targetImageUrl,
    this.targetLabel,
    this.targetType,
  });

  final String action;

  /// True when `target_type`/`target_label` were INFERRED by the migration rather than recorded.
  ///
  /// Surfaced rather than hidden: a backfilled label is the target's name *today*, not its name
  /// when the action happened, and for a deleted target there is no label at all. An operator
  /// reading an old entry needs to know which kind they are looking at.
  final bool backfilled;

  /// `admin` | `moderation` | `catalog` | `auth` | `system`. Coarse enough to filter by.
  final String category;
  final int createdAtMs;

  /// BIGSERIAL, strictly monotonic — which is what keyset pagination pages on.
  final int id;
  final String? actorHandle;
  final String? actorId;
  final Map<String, Object?>? after;
  final Map<String, Object?>? before;
  final String? detail;
  final String? targetId;

  /// The target's art, resolved at READ time — unlike `target_label`, which is captured at write
  /// time.
  ///
  /// The distinction is deliberate. A label is identity and must be a record of what the thing was
  /// called when the action happened; a picture is not identity, it is decoration that gets better
  /// over time, and pinning a cover from the day of an edit would freeze whatever placeholder the
  /// enrichment worker had reached by then. A deleted target simply has none.
  final String? targetImageUrl;
  final String? targetLabel;

  /// `user` | `artist` | `album` | `track` | `label` | `report` | `suggestion`, or absent.
  final String? targetType;

  factory AuditEntry.fromJson(Map<String, Object?> json) => AuditEntry(
    action: asString(json['action']),
    backfilled: asBool(json['backfilled']),
    category: asString(json['category']),
    createdAtMs: asInt(json['created_at_ms']),
    id: asInt(json['id']),
    actorHandle: asStringOrNull(json['actor_handle']),
    actorId: asStringOrNull(json['actor_id']),
    after: asObjectOrNull(json['after']),
    before: asObjectOrNull(json['before']),
    detail: asStringOrNull(json['detail']),
    targetId: asStringOrNull(json['target_id']),
    targetImageUrl: asStringOrNull(json['target_image_url']),
    targetLabel: asStringOrNull(json['target_label']),
    targetType: asStringOrNull(json['target_type']),
  );

  Map<String, Object?> toJson() => {
    'action': action,
    'backfilled': backfilled,
    'category': category,
    'created_at_ms': createdAtMs,
    'id': id,
    if (actorHandle != null) 'actor_handle': actorHandle,
    if (actorId != null) 'actor_id': actorId,
    if (after != null) 'after': after,
    if (before != null) 'before': before,
    if (detail != null) 'detail': detail,
    if (targetId != null) 'target_id': targetId,
    if (targetImageUrl != null) 'target_image_url': targetImageUrl,
    if (targetLabel != null) 'target_label': targetLabel,
    if (targetType != null) 'target_type': targetType,
  };
}

