  none('none'),
  active('active'),
  trialing('trialing'),
  pastDue('past_due'),
  canceled('canceled'),
  paused('paused'),
  expired('expired');

  const BillingStatus(this.wire);

  /// The string this value takes on the wire.
  final String wire;

  static BillingStatus? tryFromWire(Object? value) {
    for (final v in values) {
