/// A track row as shown in a list. `library_id` tells the player which library to stream from.
class BrowseTrack {
  const BrowseTrack({
    required this.artist,
    required this.contentHash,
    required this.durationMs,
    required this.id,
    required this.libraryId,
    required this.title,
    required this.trackRef,
    this.addedAt,
    this.advisory,
    this.album,
    this.albumId,
    this.artistId,
    this.artists,
    this.coverUrl,
    this.discNo,
    this.edition,
    this.plays,
    this.trackNo,
    this.variants,
  });

  /// Display string of all credited artists (e.g. `"Drake feat. Rihanna"`).
  final String artist;
  final String contentHash;
  final int durationMs;
  final String id;

  /// The library this playable track lives in (for grant + streaming).
  final String libraryId;
  final String title;

  /// The library's own track id, used to build the stream URL.
  final String trackRef;
  final int? addedAt;

  /// Content advisory: `"explicit"` or `"clean"` (from the file's iTunes/ID3 rating tag), `None`
  /// when unrated. Drives the EXPLICIT badge.
  final String? advisory;
  final String? album;
  final String? albumId;

  /// Primary artist id (album attribution / "main artist" navigation).
  final String? artistId;

  /// All credited artists, ordered (primary first), for per-artist links. May be empty for
  /// legacy rows synced before multi-artist support.
  final List<ArtistRef>? artists;
  final String? coverUrl;
  final int? discNo;

  /// Edition qualifier ("Deluxe", …) when this track is from a deluxe/special edition folded into
  /// the base album; `None` for the standard edition. Lets the album view badge the extra tracks.
  final String? edition;

  /// Total times this track has been played (across the Hub).
  final int? plays;
  final int? trackNo;

  /// Markers lifted out of the title on the way into the catalog: `Live`, `Remaster`, and so on.
  ///
  /// The title above is what is LEFT once these are removed, so the two are read together: a row
  /// shows the song's name and badges what kind of recording it is, instead of repeating
  /// "(Album Version (Explicit))" down every line of an album. See `crate::variants`.
  final List<TrackVariant>? variants;

  factory BrowseTrack.fromJson(Map<String, Object?> json) => BrowseTrack(
    artist: asString(json['artist']),
    contentHash: asString(json['content_hash']),
    durationMs: asInt(json['duration_ms']),
    id: asString(json['id']),
    libraryId: asString(json['library_id']),
    title: asString(json['title']),
    trackRef: asString(json['track_ref']),
    addedAt: asIntOrNull(json['added_at']),
    advisory: asStringOrNull(json['advisory']),
    album: asStringOrNull(json['album']),
    albumId: asStringOrNull(json['album_id']),
    artistId: asStringOrNull(json['artist_id']),
    artists: asListOrNull(
      json['artists'],
    )?.map((e) => ArtistRef.fromJson(asObject(e))).toList(),
    coverUrl: asStringOrNull(json['cover_url']),
    discNo: asIntOrNull(json['disc_no']),
    edition: asStringOrNull(json['edition']),
    plays: asIntOrNull(json['plays']),
    trackNo: asIntOrNull(json['track_no']),
    variants: asListOrNull(
      json['variants'],
    )?.map((e) => TrackVariant.fromWire(e)).toList(),
  );

  Map<String, Object?> toJson() => {
    'artist': artist,
    'content_hash': contentHash,
    'duration_ms': durationMs,
    'id': id,
    'library_id': libraryId,
    'title': title,
    'track_ref': trackRef,
    if (addedAt != null) 'added_at': addedAt,
    if (advisory != null) 'advisory': advisory,
    if (album != null) 'album': album,
    if (albumId != null) 'album_id': albumId,
    if (artistId != null) 'artist_id': artistId,
    if (artists != null) 'artists': artists!.map((e) => e.toJson()).toList(),
    if (coverUrl != null) 'cover_url': coverUrl,
    if (discNo != null) 'disc_no': discNo,
    if (edition != null) 'edition': edition,
    if (plays != null) 'plays': plays,
    if (trackNo != null) 'track_no': trackNo,
    if (variants != null) 'variants': variants!.map((e) => e.wire).toList(),
  };
}

/// Grain the over-time series is bucketed at, so the client can label its x-axis correctly.
enum BucketGranularity {
  hour('hour'),
  day('day'),
  week('week'),
  month('month'),
  year('year');

  const BucketGranularity(this.wire);

  /// The string this value takes on the wire.
  final String wire;

  static BucketGranularity? tryFromWire(Object? value) {
    for (final v in values) {
      if (v.wire == value) return v;
    }
    return null;
  }

  /// Falls back to [hour] for a value this build does not know,
  /// so a server that gains a variant does not crash an older client.
  static BucketGranularity fromWire(Object? value) =>
      tryFromWire(value) ?? hour;
}

/// What a capability token authorizes the holder to do.
enum CapabilityAction {
  streamRead('stream_read'),
  relayPull('relay_pull'),
  recoverManagement('recover_management');

  const CapabilityAction(this.wire);

  /// The string this value takes on the wire.
  final String wire;

  static CapabilityAction? tryFromWire(Object? value) {
    for (final v in values) {
      if (v.wire == value) return v;
    }
    return null;
  }

  /// Falls back to [streamRead] for a value this build does not know,
  /// so a server that gains a variant does not crash an older client.
  static CapabilityAction fromWire(Object? value) =>
      tryFromWire(value) ?? streamRead;
}

/// Claims inside a **capability token** - the linchpin of the data-plane security model.
///
/// Minted by the Hub only after verifying friendship + share permissions, then validated
/// **offline** by the target library against the Hub JWKS.
class CapabilityClaims {
  const CapabilityClaims({
    required this.action,
    required this.aud,
    required this.exp,
    required this.iat,
    required this.jti,
    required this.kid,
    required this.libraryId,
    required this.permissionLevel,
    required this.resource,
    required this.sub,
    this.roomId,
  });

  /// What may be done with it.
  final CapabilityAction action;

  /// Audience - the `server_id` of the library expected to honor this token.
  final String aud;
  final int exp;
  final int iat;

  /// Unique token id - enables revocation lists and replay detection.
  final String jti;
  final String kid;

  /// Library the resource lives in.
  final String libraryId;

  /// Permission level granted to the subject for this library (owner → Download, shared → per-share).
  final PermissionLevel permissionLevel;

  /// What may be accessed.
  final ResourceRef resource;

  /// Subject - the user (or, for relay, the requesting library's owner) being authorized.
  final String sub;

  /// Room context, set for relay tokens so the DJ's library can scope the grant.
  final String? roomId;

  factory CapabilityClaims.fromJson(Map<String, Object?> json) =>
      CapabilityClaims(
        action: CapabilityAction.fromWire(json['action']),
        aud: asString(json['aud']),
        exp: asInt(json['exp']),
        iat: asInt(json['iat']),
        jti: asString(json['jti']),
        kid: asString(json['kid']),
        libraryId: asString(json['library_id']),
        permissionLevel: PermissionLevel.fromWire(json['permission_level']),
        resource: ResourceRef.fromJson(asObject(json['resource'])),
        sub: asString(json['sub']),
        roomId: asStringOrNull(json['room_id']),
      );

  Map<String, Object?> toJson() => {
    'action': action.wire,
    'aud': aud,
    'exp': exp,
    'iat': iat,
    'jti': jti,
    'kid': kid,
    'library_id': libraryId,
    'permission_level': permissionLevel.wire,
    'resource': resource.toJson(),
    'sub': sub,
    if (roomId != null) 'room_id': roomId,
  };
}

