/// One page of a listener's full ranked library. Offset-paged rather than keyset: the ranking is
/// dense and recomputed per window, so there is no stable cursor to page from, and a reader jumping
/// to "page 7" expects ranks 121–140 rather than wherever a cursor happened to land.
class ChartPage {
  const ChartPage({
    required this.entries,
    required this.kind,
    required this.offset,
    required this.period,
    required this.total,
    required this.windowEnd,
    required this.windowStart,
  });

  final List<ChartEntry> entries;
  final EntityKind kind;
  final int offset;
  final Period period;

  /// Distinct entities of this kind the listener played in the window — the denominator behind
  /// "#7 of 412", and what tells the client whether another page exists.
  final int total;
  final int windowEnd;
  final int windowStart;

  factory ChartPage.fromJson(Map<String, Object?> json) => ChartPage(
    entries: asList(
      json['entries'],
    ).map((e) => ChartEntry.fromJson(asObject(e))).toList(),
    kind: EntityKind.fromWire(json['kind']),
    offset: asInt(json['offset']),
    period: Period.fromWire(json['period']),
    total: asInt(json['total']),
    windowEnd: asInt(json['window_end']),
    windowStart: asInt(json['window_start']),
  );

  Map<String, Object?> toJson() => {
    'entries': entries.map((e) => e.toJson()).toList(),
    'kind': kind.wire,
    'offset': offset,
    'period': period.wire,
    'total': total,
    'window_end': windowEnd,
    'window_start': windowStart,
  };
}

