/// Messages a client sends over the room WebSocket.
sealed class ClientMessage {
  const ClientMessage();

  /// The `type` this variant carries on the wire.
  String get type;

  static ClientMessage fromJson(Map<String, Object?> json) {
    switch (json['type']) {
      case 'join':
        return ClientMessageJoin.fromJson(json);
      case 'leave':
        return ClientMessageLeave.fromJson(json);
      case 'play':
        return ClientMessagePlay.fromJson(json);
      case 'pause':
        return ClientMessagePause.fromJson(json);
      case 'seek':
        return ClientMessageSeek.fromJson(json);
      case 'next':
        return ClientMessageNext.fromJson(json);
      case 'enqueue':
        return ClientMessageEnqueue.fromJson(json);
      case 'vote':
        return ClientMessageVote.fromJson(json);
      case 'chat':
        return ClientMessageChat.fromJson(json);
      case 'ping':
        return ClientMessagePing.fromJson(json);
      default:
        throw FormatException('Unknown ClientMessage type: ${json['type']}');
    }
  }

  Map<String, Object?> toJson();
}

