  factory Compared.fromJson(Map<String, Object?> json) => Compared(
    current: asInt(json['current']),
    previous: asInt(json['previous']),
    change: asDoubleOrNull(json['change']),
  );

  Map<String, Object?> toJson() => {
    'current': current,
    'previous': previous,
    if (change != null) 'change': change,
