/// Which kind of catalog entity a per-entity stats query is about.
enum EntityKind {
  artist('artist'),
  album('album'),
  track('track');

  const EntityKind(this.wire);

  /// The string this value takes on the wire.
  final String wire;

  static EntityKind? tryFromWire(Object? value) {
    for (final v in values) {
      if (v.wire == value) return v;
    }
    return null;
  }

  /// Falls back to [artist] for a value this build does not know,
  /// so a server that gains a variant does not crash an older client.
  static EntityKind fromWire(Object? value) => tryFromWire(value) ?? artist;
}

