/// A table the explorer will show, and what it looks like.
class ExplorerTable {
  const ExplorerTable({
    required this.columns,
    required this.key,
    required this.label,
    required this.rowCount,
    required this.titleColumn,
    this.imageColumn,
    this.rowCountCapped,
    this.sizeBytes,
  });

  final List<ExplorerColumn> columns;

  /// The key the API takes. Never a raw table name from the caller.
  final String key;
  final String label;

  /// How many rows, counted up to a cap rather than estimated.
  ///
  /// This was `reltuples`, the planner's estimate, and it was wrong in the way estimates are
  /// always wrong at small scale: `reltuples` is -1 until ANALYZE has run on the table, so a
  /// three-row table reported zero. An operator cannot tell a real zero from an unanalyzed one,
  /// which makes the whole figure worthless. A capped count is exact where it matters and honest
  /// where it stops.
  final int rowCount;

  /// The column whose value titles a row in the detail view.
  final String titleColumn;

  /// The image column, when the table has one.
  final String? imageColumn;

  /// `row_count` hit the cap and the real figure is higher.
  final bool? rowCountCapped;

  /// What the table costs on disk, indexes and TOAST included.
  final int? sizeBytes;

  factory ExplorerTable.fromJson(Map<String, Object?> json) => ExplorerTable(
    columns: asList(
      json['columns'],
    ).map((e) => ExplorerColumn.fromJson(asObject(e))).toList(),
    key: asString(json['key']),
    label: asString(json['label']),
    rowCount: asInt(json['row_count']),
    titleColumn: asString(json['title_column']),
    imageColumn: asStringOrNull(json['image_column']),
    rowCountCapped: asBoolOrNull(json['row_count_capped']),
    sizeBytes: asIntOrNull(json['size_bytes']),
  );

  Map<String, Object?> toJson() => {
    'columns': columns.map((e) => e.toJson()).toList(),
    'key': key,
    'label': label,
    'row_count': rowCount,
    'title_column': titleColumn,
    if (imageColumn != null) 'image_column': imageColumn,
    if (rowCountCapped != null) 'row_count_capped': rowCountCapped,
    if (sizeBytes != null) 'size_bytes': sizeBytes,
  };
}

