/// A friendship edge as returned by the Hub. `user_a` is always the lexicographically smaller id
/// so each undirected edge has a single canonical row.
class Friendship {
  const Friendship({
    required this.createdAt,
    required this.requestedBy,
    required this.status,
    required this.userA,
    required this.userB,
  });

  final int createdAt;

  /// Who initiated the pending request (for UI: incoming vs outgoing).
  final String requestedBy;
  final FriendshipStatus status;
  final String userA;
  final String userB;

  factory Friendship.fromJson(Map<String, Object?> json) => Friendship(
    createdAt: asInt(json['created_at']),
    requestedBy: asString(json['requested_by']),
    status: FriendshipStatus.fromWire(json['status']),
    userA: asString(json['user_a']),
    userB: asString(json['user_b']),
  );

  Map<String, Object?> toJson() => {
    'created_at': createdAt,
    'requested_by': requestedBy,
    'status': status.wire,
    'user_a': userA,
    'user_b': userB,
  };
}

/// Lifecycle of a friendship edge.
enum FriendshipStatus {
  pending('pending'),
  accepted('accepted'),
  blocked('blocked');

  const FriendshipStatus(this.wire);

  /// The string this value takes on the wire.
  final String wire;

  static FriendshipStatus? tryFromWire(Object? value) {
    for (final v in values) {
      if (v.wire == value) return v;
    }
    return null;
  }

  /// Falls back to [pending] for a value this build does not know,
  /// so a server that gains a variant does not crash an older client.
  static FriendshipStatus fromWire(Object? value) =>
      tryFromWire(value) ?? pending;
}

