/// One history-import job, as created by `POST /v1/me/imports` and polled from
/// `GET /v1/me/imports/{id}`.
///
/// The counters partition `total_rows`: every row in the file ends up imported, a duplicate of an
/// already-stored event, or skipped (sub-30-second Spotify plays, podcast rows, unparseable rows).
/// `matched_rows` counts, among the imported, those resolved to a catalog track; the rest are
/// stored with their artist/title text and match later if that music arrives.
class ImportJob {
  const ImportJob({
    required this.createdAt,
    required this.duplicateRows,
    required this.id,
    required this.importedRows,
    required this.matchedRows,
    required this.skippedRows,
    required this.source,
    required this.status,
    required this.totalRows,
    this.error,
    this.finishedAt,
  });

  final int createdAt;

  /// Rows that were already present (same deterministic event id), so nothing was inserted.
  final int duplicateRows;
  final String id;

  /// Rows inserted as new listening events so far.
  final int importedRows;

  /// Imported rows resolved to a track in a library the owner can access.
  final int matchedRows;

  /// Rows not worth importing: sub-30-second Spotify plays, podcast rows, unparseable rows.
  final int skippedRows;
  final ImportSource source;
  final ImportJobStatus status;

  /// Rows found in the file. `0` until parsing finishes.
  final int totalRows;

  /// A stable failure code (`"malformed"`, `"internal"`, ...) when `status` is `Failed`; clients
  /// localize it.
  final String? error;
  final int? finishedAt;

  factory ImportJob.fromJson(Map<String, Object?> json) => ImportJob(
    createdAt: asInt(json['created_at']),
    duplicateRows: asInt(json['duplicate_rows']),
    id: asString(json['id']),
    importedRows: asInt(json['imported_rows']),
    matchedRows: asInt(json['matched_rows']),
    skippedRows: asInt(json['skipped_rows']),
    source: ImportSource.fromWire(json['source']),
    status: ImportJobStatus.fromWire(json['status']),
    totalRows: asInt(json['total_rows']),
    error: asStringOrNull(json['error']),
    finishedAt: asIntOrNull(json['finished_at']),
  );

  Map<String, Object?> toJson() => {
    'created_at': createdAt,
    'duplicate_rows': duplicateRows,
    'id': id,
    'imported_rows': importedRows,
    'matched_rows': matchedRows,
    'skipped_rows': skippedRows,
    'source': source.wire,
    'status': status.wire,
    'total_rows': totalRows,
    if (error != null) 'error': error,
    if (finishedAt != null) 'finished_at': finishedAt,
  };
}

/// Lifecycle of an import job. Terminal states are `Done` and `Failed`; a client polls until it
/// reaches one.
enum ImportJobStatus {
  pending('pending'),
  running('running'),
  done('done'),
  failed('failed');

  const ImportJobStatus(this.wire);

  /// The string this value takes on the wire.
  final String wire;

  static ImportJobStatus? tryFromWire(Object? value) {
    for (final v in values) {
      if (v.wire == value) return v;
    }
    return null;
  }

  /// Falls back to [pending] for a value this build does not know,
  /// so a server that gains a variant does not crash an older client.
  static ImportJobStatus fromWire(Object? value) =>
      tryFromWire(value) ?? pending;
}

/// `GET /v1/me/imports`: the caller's recent import jobs, newest first.
class ImportJobsResponse {
  const ImportJobsResponse({required this.jobs});

  final List<ImportJob> jobs;

  factory ImportJobsResponse.fromJson(Map<String, Object?> json) =>
      ImportJobsResponse(
        jobs: asList(
          json['jobs'],
        ).map((e) => ImportJob.fromJson(asObject(e))).toList(),
      );

  Map<String, Object?> toJson() => {
    'jobs': jobs.map((e) => e.toJson()).toList(),
  };
}

/// Which service an uploaded history file came from.
///
/// Detected from the file's content server-side; a client may also state it explicitly
/// (`POST /v1/me/imports?source=`), which is validated against the content rather than trusted.
enum ImportSource {
  spotify('spotify'),
  lastfm('lastfm');

  const ImportSource(this.wire);

  /// The string this value takes on the wire.
  final String wire;

  static ImportSource? tryFromWire(Object? value) {
    for (final v in values) {
      if (v.wire == value) return v;
    }
    return null;
  }

  /// Falls back to [spotify] for a value this build does not know,
  /// so a server that gains a variant does not crash an older client.
  static ImportSource fromWire(Object? value) => tryFromWire(value) ?? spotify;
}

/// What a Hub says about itself to a client that has not signed in — capability flags, plus enough
/// identity for the desktop app's hub picker.
///
/// Unauthenticated by necessity: the desktop app calls this on a URL the user has just typed, to
/// answer "is this a Chordia Hub, what do we call it, and does it do Discord" before there is any
/// account here to authenticate with. A 200 with this shape is itself the "yes, this is a Hub"
/// check.
class InstanceInfo {
  const InstanceInfo({
    required this.discordOauth,
    required this.frontendUrl,
    required this.name,
    required this.socialEnabled,
    required this.version,
    this.accent,
    this.billingEnabled,
    this.discordClientId,
  });

  /// Whether "Continue with Discord" will work here. False when the operator never configured a
  /// Discord app, and a button that leads to a 500 is worse than no button.
  final bool discordOauth;

  /// The Hub's canonical **web** frontend. The desktop app anchors the links its users copy here,
  /// because its own origin (`https://tauri.localhost`) means nothing to whoever receives one.
  final String frontendUrl;

  /// Operator-facing name, shown in the desktop hub picker. Self-hosters run several, and "Hub"
  /// three times is not a picker.
  final String name;

  /// Whether the follow graph and public profiles are enabled on this instance.
  final bool socialEnabled;

  /// Hub software version, for support and for a client that wants to warn about a stale server.
  final String version;

  /// The accent this deployment wears before a listener has chosen their own — a preset name or a
  /// `#rrggbb`. `None` means the operator has not set one and the app's own default stands, which
  /// is different from their choosing that colour: it keeps following the default if it changes.
  ///
  /// Public because it themes the sign-in and landing screens, which nobody is signed in to.
  final String? accent;

  /// Whether this deployment sells subscriptions. False on a self-hosted Hub with no payment
  /// provider configured — which is the default, and where every client must render no pricing,
  /// no plan tab and no upsell at all.
  final bool? billingEnabled;

  /// This deployment's Discord application id, when it has one.
  ///
  /// Also its Rich Presence application id — Discord has one identifier for both, so the desktop
  /// app publishes presence under whichever application the operator already configured for
  /// sign-in rather than carrying a second one baked in at build time.
  ///
  /// Public because it already is: this value appears in the query string of every OAuth
  /// authorize URL a browser visits. The client *secret* is the confidential half and stays on
  /// the Hub. Derived from the same config as `discord_oauth` above, so the two cannot disagree.
  final String? discordClientId;

  factory InstanceInfo.fromJson(Map<String, Object?> json) => InstanceInfo(
    discordOauth: asBool(json['discord_oauth']),
    frontendUrl: asString(json['frontend_url']),
    name: asString(json['name']),
    socialEnabled: asBool(json['social_enabled']),
    version: asString(json['version']),
    accent: asStringOrNull(json['accent']),
    billingEnabled: asBoolOrNull(json['billing_enabled']),
    discordClientId: asStringOrNull(json['discord_client_id']),
  );

  Map<String, Object?> toJson() => {
    'discord_oauth': discordOauth,
    'frontend_url': frontendUrl,
    'name': name,
    'social_enabled': socialEnabled,
    'version': version,
    if (accent != null) 'accent': accent,
    if (billingEnabled != null) 'billing_enabled': billingEnabled,
    if (discordClientId != null) 'discord_client_id': discordClientId,
  };
}

