      LikedPoint(month: asString(json['month']), total: asInt(json['total']));

  Map<String, Object?> toJson() => {'month': month, 'total': total};
}

/// The caller's liked songs in numbers, for the disclosure on the Liked Songs page.
///
/// Everything derived from listening honours the caller's retention floor, so the ratios below
/// describe the window their insights already show rather than quietly reaching past it.
class LikedStats {
  const LikedStats({
    required this.history,
    required this.likedPlays,
    required this.neverPlayed,
    required this.playedLiked,
    required this.playedTracks,
    required this.topArtists,
    required this.total,
    required this.totalDurationMs,
    required this.unlikedFavourites,
    this.firstLiked,
    this.lastLiked,
  });

  /// Cumulative growth, one point per month from the first like to now.
  final List<LikedPoint> history;

  /// The caller's plays across their liked tracks.
  final int likedPlays;

  /// Liked tracks with no play on record in the window. "Saved for later" made countable.
  final int neverPlayed;

  /// How many of those they went on to like. With `played_tracks` at 0 the ratio is undefined,
  /// which is why both numbers are sent rather than a percentage computed here.
  final int playedLiked;

  /// Distinct tracks the caller has played inside the retention window.
  final int playedTracks;

  /// Artists best represented in the liked list.
  final List<LikedArtist> topArtists;

  /// Liked tracks right now.
  final int total;

  /// Their combined length. `0` when none of them resolve to a catalog track with a duration.
  final int totalDurationMs;

  /// The caller's most-played tracks that they have NOT liked — the songs the heart missed.
  final List<TopItem> unlikedFavourites;
  final int? firstLiked;
  final int? lastLiked;

  factory LikedStats.fromJson(Map<String, Object?> json) => LikedStats(
    history: asList(
      json['history'],
    ).map((e) => LikedPoint.fromJson(asObject(e))).toList(),
    likedPlays: asInt(json['liked_plays']),
    neverPlayed: asInt(json['never_played']),
    playedLiked: asInt(json['played_liked']),
    playedTracks: asInt(json['played_tracks']),
    topArtists: asList(
      json['top_artists'],
    ).map((e) => LikedArtist.fromJson(asObject(e))).toList(),
    total: asInt(json['total']),
    totalDurationMs: asInt(json['total_duration_ms']),
    unlikedFavourites: asList(
      json['unliked_favourites'],
    ).map((e) => TopItem.fromJson(asObject(e))).toList(),
    firstLiked: asIntOrNull(json['first_liked']),
    lastLiked: asIntOrNull(json['last_liked']),
  );

  Map<String, Object?> toJson() => {
    'history': history.map((e) => e.toJson()).toList(),
    'liked_plays': likedPlays,
    'never_played': neverPlayed,
    'played_liked': playedLiked,
    'played_tracks': playedTracks,
    'top_artists': topArtists.map((e) => e.toJson()).toList(),
    'total': total,
    'total_duration_ms': totalDurationMs,
    'unliked_favourites': unlikedFavourites.map((e) => e.toJson()).toList(),
    if (firstLiked != null) 'first_liked': firstLiked,
    if (lastLiked != null) 'last_liked': lastLiked,
