    required this.weekday,
    required this.windowEnd,
    required this.windowStart,
  });

  /// Plays by local hour-of-day, exactly 24 entries (index = hour 0 to 23).
  final List<int> clock;
  final ClockGrid clockGrid;
  final BucketGranularity granularity;

  /// Plays bucketed across the window, chronological. Daily for windows up to a year; monthly for
  /// `Overall`. Doubles as a calendar-heatmap source at day granularity.
  final List<TimeBucket> overTime;
  final Period period;

  /// IANA timezone used for the local calendar window and time buckets.
  final String timezone;

  /// Plays by local day-of-week, exactly 7 entries (index 0 = Sunday through 6 = Saturday).
  final List<int> weekday;
  final int windowEnd;
  final int windowStart;

  factory ListeningCharts.fromJson(Map<String, Object?> json) =>
      ListeningCharts(
        clock: asList(json['clock']).map((e) => asInt(e)).toList(),
        clockGrid: ClockGrid.fromJson(asObject(json['clock_grid'])),
        granularity: BucketGranularity.fromWire(json['granularity']),
        overTime: asList(
          json['over_time'],
        ).map((e) => TimeBucket.fromJson(asObject(e))).toList(),
        period: Period.fromWire(json['period']),
        timezone: asString(json['timezone']),
        weekday: asList(json['weekday']).map((e) => asInt(e)).toList(),
        windowEnd: asInt(json['window_end']),
        windowStart: asInt(json['window_start']),
      );

  Map<String, Object?> toJson() => {
    'clock': clock,
    'clock_grid': clockGrid.toJson(),
    'granularity': granularity.wire,
