/// A single listening event. Created client-side with a UUIDv7 `event_id` so it doubles as the
/// **idempotency key** - replays/reinstalls never double-count.
class ListeningEvent {
  const ListeningEvent({
    required this.clientType,
    required this.durationMs,
    required this.eventId,
    required this.fingerprint,
    required this.msPlayed,
    required this.source,
    required this.startedAt,
    this.artist,
    this.libraryId,
    this.playlistId,
    this.roomId,
    this.title,
  });

  final ClientType clientType;

  /// Track duration for threshold/skew calculations.
  final int durationMs;

  /// UUIDv7 - time-sortable + idempotency key.
  final String eventId;

  /// Identity of what was played (resolved to the canonical catalog server-side).
  final TrackFingerprint fingerprint;

  /// Milliseconds actually played.
  final int msPlayed;
  final PlaybackSource source;

  /// When playback started (epoch millis, client clock).
  final int startedAt;

  /// Artist display string exactly as reported by the client. This is deliberately distinct from
  /// `fingerprint.artist_norm`, which is only a fuzzy-matching key.
  final String? artist;

  /// Library streamed from, when applicable.
  final String? libraryId;

  /// Playlist the track was played from, when the play originated in a playlist context.
  final String? playlistId;

  /// Room the track was heard in, when applicable.
  final String? roomId;

  /// Track title exactly as reported by the client. Optional for compatibility with older clients;
  /// resolved events can fall back to the canonical catalog title.
  final String? title;

  factory ListeningEvent.fromJson(Map<String, Object?> json) => ListeningEvent(
    clientType: ClientType.fromWire(json['client_type']),
    durationMs: asInt(json['duration_ms']),
    eventId: asString(json['event_id']),
    fingerprint: TrackFingerprint.fromJson(asObject(json['fingerprint'])),
    msPlayed: asInt(json['ms_played']),
    source: PlaybackSource.fromWire(json['source']),
    startedAt: asInt(json['started_at']),
    artist: asStringOrNull(json['artist']),
    libraryId: asStringOrNull(json['library_id']),
    playlistId: asStringOrNull(json['playlist_id']),
    roomId: asStringOrNull(json['room_id']),
    title: asStringOrNull(json['title']),
  );

  Map<String, Object?> toJson() => {
    'client_type': clientType.wire,
    'duration_ms': durationMs,
    'event_id': eventId,
    'fingerprint': fingerprint.toJson(),
    'ms_played': msPlayed,
    'source': source.wire,
    'started_at': startedAt,
    if (artist != null) 'artist': artist,
    if (libraryId != null) 'library_id': libraryId,
    if (playlistId != null) 'playlist_id': playlistId,
    if (roomId != null) 'room_id': roomId,
    if (title != null) 'title': title,
  };
}

/// Personal listening records and all-time milestones for one reporting window.
class ListeningRecords {
  const ListeningRecords({
    required this.activeDays,
    required this.avgPlaysPerDay,
    required this.avgPlaysPerDayCompared,
    required this.biggestDayCompared,
    required this.milestones,
    required this.period,
    required this.timezone,
    required this.topSessions,
    required this.windowEnd,
    required this.windowStart,
    this.biggestDay,
    this.currentStreak,
    this.dayStatsPending,
    this.firstScrobble,
    this.longestStreak,
  });

  final int activeDays;

  /// Mean plays per calendar day in the window, including silent days.
  final double avgPlaysPerDay;

  /// Current and previous averages rounded to the nearest whole play per day. The precise current
  /// value remains available in `avg_plays_per_day`.
  final Compared avgPlaysPerDayCompared;

  /// Play count of the busiest local-calendar day in each window (zero when a window is empty).
  final Compared biggestDayCompared;

  /// Round-number play milestones, ascending.
  final List<Milestone> milestones;
  final Period period;
  final String timezone;

  /// Longest sessions first, capped at ten.
  final List<ListeningSession> topSessions;
  final int windowEnd;
  final int windowStart;
  final TimeBucket? biggestDay;
  final Streak? currentStreak;

  /// True when the day-grained figures could not be computed yet: the UTC report is served from
  /// the daily rollup, and on a Hub whose aggregator has never completed a pass there is no
  /// rollup to read. The streaks, `active_days`, the averages and `biggest_day` above are then
  /// placeholders rather than facts, and a client should say "still being computed" instead of
  /// rendering a zero-day history as if it were real. Sessions and milestones are unaffected
  /// (they scan the fact table directly), as are non-UTC reports.
  final bool? dayStatsPending;
  final Milestone? firstScrobble;
  final Streak? longestStreak;

  factory ListeningRecords.fromJson(Map<String, Object?> json) =>
      ListeningRecords(
        activeDays: asInt(json['active_days']),
        avgPlaysPerDay: asDouble(json['avg_plays_per_day']),
        avgPlaysPerDayCompared: Compared.fromJson(
          asObject(json['avg_plays_per_day_compared']),
        ),
        biggestDayCompared: Compared.fromJson(
          asObject(json['biggest_day_compared']),
        ),
        milestones: asList(
          json['milestones'],
        ).map((e) => Milestone.fromJson(asObject(e))).toList(),
        period: Period.fromWire(json['period']),
        timezone: asString(json['timezone']),
        topSessions: asList(
          json['top_sessions'],
        ).map((e) => ListeningSession.fromJson(asObject(e))).toList(),
        windowEnd: asInt(json['window_end']),
        windowStart: asInt(json['window_start']),
        biggestDay: json['biggest_day'] == null
            ? null
            : TimeBucket.fromJson(asObject(json['biggest_day'])),
        currentStreak: json['current_streak'] == null
            ? null
            : Streak.fromJson(asObject(json['current_streak'])),
        dayStatsPending: asBoolOrNull(json['day_stats_pending']),
        firstScrobble: json['first_scrobble'] == null
            ? null
            : Milestone.fromJson(asObject(json['first_scrobble'])),
        longestStreak: json['longest_streak'] == null
            ? null
            : Streak.fromJson(asObject(json['longest_streak'])),
      );

  Map<String, Object?> toJson() => {
    'active_days': activeDays,
    'avg_plays_per_day': avgPlaysPerDay,
    'avg_plays_per_day_compared': avgPlaysPerDayCompared.toJson(),
    'biggest_day_compared': biggestDayCompared.toJson(),
    'milestones': milestones.map((e) => e.toJson()).toList(),
    'period': period.wire,
    'timezone': timezone,
    'top_sessions': topSessions.map((e) => e.toJson()).toList(),
    'window_end': windowEnd,
    'window_start': windowStart,
    if (biggestDay != null) 'biggest_day': biggestDay!.toJson(),
    if (currentStreak != null) 'current_streak': currentStreak!.toJson(),
    if (dayStatsPending != null) 'day_stats_pending': dayStatsPending,
    if (firstScrobble != null) 'first_scrobble': firstScrobble!.toJson(),
    if (longestStreak != null) 'longest_streak': longestStreak!.toJson(),
  };
}

