  unsynced('UNSYNCED'),
  lineSYNCED('LINE_SYNCED');

  const LyricsSyncType(this.wire);

  /// The string this value takes on the wire.
  final String wire;

  static LyricsSyncType? tryFromWire(Object? value) {
    for (final v in values) {
      if (v.wire == value) return v;
    }
    return null;
  }

  /// Falls back to [unsynced] for a value this build does not know,
