    'id': id,
    'period': period.wire,
    'top_tracks': topTracks.map((e) => e.toJson()).toList(),
    'total_ms_played': totalMsPlayed,
    'total_plays': totalPlays,
    'tracking_since': trackingSince,
    'trend': trend.map((e) => e.toJson()).toList(),
    'window_end': windowEnd,
    'window_start': windowStart,
    if (firstPlayed != null) 'first_played': firstPlayed,
    if (globalPlays != null) 'global_plays': globalPlays,
    if (lastPlayed != null) 'last_played': lastPlayed,
    if (scope != null) 'scope': scope!.wire,
