/// A badge on a profile.
///
/// Tagged by `kind` with the detail inline, rather than a flat struct of nullable fields: a badge's
/// detail is exactly what makes it that badge, and every renderer has to switch on the kind anyway.
sealed class ProfileBadge {
  const ProfileBadge();

  /// The `kind` this variant carries on the wire.
  String get kind;

  static ProfileBadge fromJson(Map<String, Object?> json) {
    switch (json['kind']) {
      case 'developer':
        return ProfileBadgeDeveloper.fromJson(json);
      case 'staff':
        return ProfileBadgeStaff.fromJson(json);
      case 'translator':
        return ProfileBadgeTranslator.fromJson(json);
      case 'early_bird':
        return ProfileBadgeEarlyBird.fromJson(json);
      case 'early_supporter':
        return ProfileBadgeEarlySupporter.fromJson(json);
      case 'sonic':
        return ProfileBadgeSonic.fromJson(json);
      case 'super_sonic':
        return ProfileBadgeSuperSonic.fromJson(json);
      default:
        throw FormatException('Unknown ProfileBadge kind: ${json['kind']}');
    }
  }

  Map<String, Object?> toJson();
}

