/// A user's shareable public listening profile. Listening stats are populated only when the viewer
/// is allowed to see them (per the target's scrobble privacy); otherwise `private` is true and the
/// lists are empty.
class PublicProfile {
  const PublicProfile({
    required this.createdAt,
    required this.private,
    required this.recent,
    required this.topArtists,
    required this.topTracks,
    required this.totalPlays,
    required this.user,
    this.accent,
    this.badges,
    this.bannerUrl,
    this.bio,
    this.canFollow,
    this.followedArtists,
    this.followerCount,
    this.followersVisible,
    this.followingCount,
    this.followingVisible,
    this.followsViewer,
    this.friendship,
    this.hidden,
    this.links,
    this.playlistCount,
    this.playlists,
    this.viewerFollows,
  });

  /// When the account was created (epoch millis).
  final int createdAt;

  /// True when the viewer may not see this user's **listening activity** — `total_plays`,
  /// `top_artists`, `top_tracks` and `recent` are then empty. Kept under its original name for
  /// compatibility; it says nothing about the profile's other surfaces, which carry their own
  /// visibility signals below.
  final bool private;
  final List<RecentPlay> recent;
  final List<TopItem> topArtists;
  final List<TopItem> topTracks;
  final int totalPlays;
  final PublicUser user;
  final ProfileAccent? accent;

  /// Badges this account carries. Present on the locked shell too: a badge is identity, like the
  /// handle, and withholding it would make a moderator unrecognisable on exactly the profile where
  /// knowing they are staff matters.
  final List<ProfileBadge>? badges;

  /// Resolved banner image URL (the Hub image endpoint), when one is set.
  final String? bannerUrl;

  /// Free-text profile bio.
  final String? bio;

  /// Whether the viewer may follow this account (false when already following, when it is their
  /// own profile, or when the target is not open to follows).
  final bool? canFollow;

  /// The user's followed artists, with the same `None` = not visible / `Some([])` = visible and
  /// empty contract as `playlists`.
  final List<ProfileArtist>? followedArtists;
  final int? followerCount;

  /// Whether the viewer may open the followers list.
  final bool? followersVisible;
  final int? followingCount;

  /// Whether the viewer may open the following list.
  final bool? followingVisible;

  /// This account follows the viewer.
  final bool? followsViewer;
  final FriendshipStatus? friendship;

  /// **The whole profile is withheld** — the viewer may not see this account at all, and every
  /// field below is a placeholder rather than a fact.
  ///
  /// Distinct from `private`, which walls only the listening activity. The two are different
  /// walls with different copy: conflating them produces a page announcing "this profile is
  /// private" while showing the person's bio, banner and links.
  ///
  /// Explicit rather than inferred. The locked shell is a zeroed DTO, and a genuinely visible
  /// profile can produce a byte-identical one — a new account with default settings, no bio and
  /// no followers, or ANY profile on an instance with the social layer switched off. A client
  /// guessing from field shape therefore walls real profiles, which is precisely the "client
  /// decides visibility" mistake the rest of this DTO is shaped to prevent.
  final bool? hidden;
  final List<ProfileLink>? links;
  final int? playlistCount;

  /// The user's playlists. **The `Option` IS the visibility signal**: `None` means the viewer may
  /// not see this surface at all (render nothing), `Some([])` means it is visible and empty
  /// (render the empty state). The client never decides visibility — the server has already
  /// applied `playlists_visibility` and each playlist's own `PlaylistVisibility`.
  final List<Playlist>? playlists;

  /// The viewer follows this account.
  final bool? viewerFollows;

  factory PublicProfile.fromJson(Map<String, Object?> json) => PublicProfile(
    createdAt: asInt(json['created_at']),
    private: asBool(json['private']),
    recent: asList(
      json['recent'],
    ).map((e) => RecentPlay.fromJson(asObject(e))).toList(),
    topArtists: asList(
      json['top_artists'],
    ).map((e) => TopItem.fromJson(asObject(e))).toList(),
    topTracks: asList(
      json['top_tracks'],
    ).map((e) => TopItem.fromJson(asObject(e))).toList(),
    totalPlays: asInt(json['total_plays']),
    user: PublicUser.fromJson(asObject(json['user'])),
    accent: json['accent'] == null
        ? null
        : ProfileAccent.fromJson(asObject(json['accent'])),
    badges: asListOrNull(
      json['badges'],
    )?.map((e) => ProfileBadge.fromJson(asObject(e))).toList(),
    bannerUrl: asStringOrNull(json['banner_url']),
    bio: asStringOrNull(json['bio']),
    canFollow: asBoolOrNull(json['can_follow']),
    followedArtists: asListOrNull(
      json['followed_artists'],
    )?.map((e) => ProfileArtist.fromJson(asObject(e))).toList(),
    followerCount: asIntOrNull(json['follower_count']),
    followersVisible: asBoolOrNull(json['followers_visible']),
    followingCount: asIntOrNull(json['following_count']),
    followingVisible: asBoolOrNull(json['following_visible']),
    followsViewer: asBoolOrNull(json['follows_viewer']),
    friendship: FriendshipStatus.tryFromWire(json['friendship']),
    hidden: asBoolOrNull(json['hidden']),
    links: asListOrNull(
      json['links'],
    )?.map((e) => ProfileLink.fromJson(asObject(e))).toList(),
    playlistCount: asIntOrNull(json['playlist_count']),
    playlists: asListOrNull(
      json['playlists'],
    )?.map((e) => Playlist.fromJson(asObject(e))).toList(),
    viewerFollows: asBoolOrNull(json['viewer_follows']),
  );

  Map<String, Object?> toJson() => {
    'created_at': createdAt,
    'private': private,
    'recent': recent.map((e) => e.toJson()).toList(),
    'top_artists': topArtists.map((e) => e.toJson()).toList(),
    'top_tracks': topTracks.map((e) => e.toJson()).toList(),
    'total_plays': totalPlays,
    'user': user.toJson(),
    if (accent != null) 'accent': accent!.toJson(),
    if (badges != null) 'badges': badges!.map((e) => e.toJson()).toList(),
    if (bannerUrl != null) 'banner_url': bannerUrl,
    if (bio != null) 'bio': bio,
    if (canFollow != null) 'can_follow': canFollow,
    if (followedArtists != null)
      'followed_artists': followedArtists!.map((e) => e.toJson()).toList(),
    if (followerCount != null) 'follower_count': followerCount,
    if (followersVisible != null) 'followers_visible': followersVisible,
    if (followingCount != null) 'following_count': followingCount,
    if (followingVisible != null) 'following_visible': followingVisible,
    if (followsViewer != null) 'follows_viewer': followsViewer,
    if (friendship != null) 'friendship': friendship!.wire,
    if (hidden != null) 'hidden': hidden,
    if (links != null) 'links': links!.map((e) => e.toJson()).toList(),
    if (playlistCount != null) 'playlist_count': playlistCount,
    if (playlists != null)
      'playlists': playlists!.map((e) => e.toJson()).toList(),
    if (viewerFollows != null) 'viewer_follows': viewerFollows,
  };
}

