/// Listener-selectable quality tier. `Original` is the default and is byte-for-byte lossless;
/// lower tiers are produced by on-the-fly transcode and may be auto-selected when
/// `auto_downgrade` is enabled and bandwidth can't sustain the current tier.
enum QualityProfile {
  original('original'),
  high('high'),
  normal('normal'),
  dataSaver('data_saver');

  const QualityProfile(this.wire);

  /// The string this value takes on the wire.
  final String wire;

  static QualityProfile? tryFromWire(Object? value) {
    for (final v in values) {
      if (v.wire == value) return v;
    }
    return null;
  }

  /// Falls back to [original] for a value this build does not know,
  /// so a server that gains a variant does not crash an older client.
  static QualityProfile fromWire(Object? value) =>
      tryFromWire(value) ?? original;
}

