/// What the backfill has done so far, and whether it is still going.
class RecompressState {
  const RecompressState({
    required this.afterBytes,
    required this.beforeBytes,
    required this.finished,
    required this.processed,
    required this.remaining,
    required this.running,
    required this.skipped,
    required this.stopping,
    this.error,
  });

  final int afterBytes;

  /// Bytes the processed images occupied before and after.
  final int beforeBytes;

  /// The run reached the end of the queue rather than being stopped.
  final bool finished;

  /// Images re-encoded so far in this run.
  final int processed;

  /// Oversized images still waiting, as of the last completed batch.
  final int remaining;

  /// A run is in flight. Poll while this is true.
  final bool running;

  /// Images looked at and left alone: already small enough, or they would not decode.
  final int skipped;

  /// A stop was asked for and the current batch is finishing.
  final bool stopping;

  /// Why the run stopped early, if it did. Shown to the operator rather than swallowed: a
  /// backfill that quietly gives up looks exactly like one that finished.
  final String? error;

  factory RecompressState.fromJson(Map<String, Object?> json) =>
      RecompressState(
        afterBytes: asInt(json['after_bytes']),
        beforeBytes: asInt(json['before_bytes']),
        finished: asBool(json['finished']),
        processed: asInt(json['processed']),
        remaining: asInt(json['remaining']),
        running: asBool(json['running']),
        skipped: asInt(json['skipped']),
        stopping: asBool(json['stopping']),
        error: asStringOrNull(json['error']),
      );

  Map<String, Object?> toJson() => {
    'after_bytes': afterBytes,
    'before_bytes': beforeBytes,
    'finished': finished,
    'processed': processed,
    'remaining': remaining,
    'running': running,
    'skipped': skipped,
    'stopping': stopping,
    if (error != null) 'error': error,
  };
}

