/// The resource a capability token is scoped to.
sealed class ResourceRef {
  const ResourceRef();

  /// The `kind` this variant carries on the wire.
  String get kind;

  static ResourceRef fromJson(Map<String, Object?> json) {
    switch (json['kind']) {
      case 'track':
        return ResourceRefTrack.fromJson(json);
      case 'album':
        return ResourceRefAlbum.fromJson(json);
      case 'library':
        return ResourceRefLibrary.fromJson(json);
      default:
        throw FormatException('Unknown ResourceRef kind: ${json['kind']}');
    }
  }

