/// Messages the `dj` service broadcasts to room clients.
sealed class ServerMessage {
  const ServerMessage();

  /// The `type` this variant carries on the wire.
  String get type;

  static ServerMessage fromJson(Map<String, Object?> json) {
    switch (json['type']) {
      case 'snapshot':
        return ServerMessageSnapshot.fromJson(json);
      case 'now_playing':
        return ServerMessageNowPlaying.fromJson(json);
      case 'queue_updated':
        return ServerMessageQueueUpdated.fromJson(json);
      case 'listener_joined':
        return ServerMessageListenerJoined.fromJson(json);
      case 'listener_left':
        return ServerMessageListenerLeft.fromJson(json);
      case 'dj_changed':
        return ServerMessageDjChanged.fromJson(json);
      case 'chat':
        return ServerMessageChat.fromJson(json);
      case 'pong':
        return ServerMessagePong.fromJson(json);
      case 'error':
        return ServerMessageError.fromJson(json);
      default:
        throw FormatException('Unknown ServerMessage type: ${json['type']}');
    }
  }

  Map<String, Object?> toJson();
}

