/// One rule: `<field> <op> <value>`. `value` is always a string; the Hub parses it per field.
class SmartCondition {
  const SmartCondition({
    required this.field,
    required this.op,
    required this.value,
    this.period,
    this.value2,
    this.valuesValue,
  });

  final SmartField field;
  final SmartOp op;
  final String value;
  final SmartPeriod? period;

  /// Upper bound for [`SmartOp::Between`]; ignored by every other operator.
  final String? value2;

  /// Every value this rule accepts, matched as OR: `artist is A, B, C`. Empty means the rule is
  /// the single `value` above, which is how every rule written before this field existed reads.
  ///
  /// `value` is kept in sync with the first entry rather than being emptied, so a reader that
  /// predates this field still resolves the rule to something sensible instead of to nothing.
  /// Only the text fields use it; a numeric or date rule ignores it.
  final List<String>? valuesValue;

  factory SmartCondition.fromJson(Map<String, Object?> json) => SmartCondition(
    field: SmartField.fromWire(json['field']),
    op: SmartOp.fromWire(json['op']),
    value: asString(json['value']),
    period: json['period'] == null
        ? null
        : SmartPeriod.fromJson(asObject(json['period'])),
    value2: asStringOrNull(json['value2']),
    valuesValue: asListOrNull(json['values'])?.map((e) => asString(e)).toList(),
  );

  Map<String, Object?> toJson() => {
    'field': field.wire,
    'op': op.wire,
    'value': value,
    if (period != null) 'period': period!.toJson(),
    if (value2 != null) 'value2': value2,
    if (valuesValue != null) 'values': valuesValue,
  };
}

/// The track attribute a condition tests.
///
/// The first seven are catalog facts. The rest describe the CALLER's relationship with the track —
/// when it arrived, when they last played it, how often — which is what makes rules like "on repeat
/// this month" or "liked but not played in a year" expressible at all.
enum SmartField {
  artist('artist'),
  title('title'),
  album('album'),
  genre('genre'),
  year('year'),
  plays('plays'),
  liked('liked'),
  duration('duration'),
  addedAt('added_at'),
  lastPlayed('last_played'),
  firstPlayed('first_played'),
  myPlays('my_plays'),
  releaseDate('release_date'),
  label('label'),
  explicit('explicit'),
  versionType('version_type');

  const SmartField(this.wire);

  /// The string this value takes on the wire.
  final String wire;

  static SmartField? tryFromWire(Object? value) {
    for (final v in values) {
      if (v.wire == value) return v;
    }
    return null;
  }

  /// Falls back to [artist] for a value this build does not know,
  /// so a server that gains a variant does not crash an older client.
  static SmartField fromWire(Object? value) => tryFromWire(value) ?? artist;
}

/// Whether all conditions must match (AND) or any (OR).
enum SmartMatch {
  all('all'),
  any('any');

  const SmartMatch(this.wire);

  /// The string this value takes on the wire.
  final String wire;

  static SmartMatch? tryFromWire(Object? value) {
    for (final v in values) {
      if (v.wire == value) return v;
    }
    return null;
  }

  /// Falls back to [all] for a value this build does not know,
  /// so a server that gains a variant does not crash an older client.
  static SmartMatch fromWire(Object? value) => tryFromWire(value) ?? all;
}

/// How a condition compares the field to its value.
enum SmartOp {
  contains('contains'),
  equals('equals'),
  gte('gte'),
  lte('lte'),
  isValue('is'),
  before('before'),
  after('after'),
  inLast('in_last'),
  notInLast('not_in_last'),
  between('between'),
  notContains('not_contains'),
  notEquals('not_equals');

  const SmartOp(this.wire);

  /// The string this value takes on the wire.
  final String wire;

  static SmartOp? tryFromWire(Object? value) {
    for (final v in values) {
      if (v.wire == value) return v;
    }
    return null;
  }

  /// Falls back to [contains] for a value this build does not know,
  /// so a server that gains a variant does not crash an older client.
  static SmartOp fromWire(Object? value) => tryFromWire(value) ?? contains;
}

/// A window of listening history, for [`SmartField::MyPlays`] and period-scoped sorting.
///
/// Calendar and rolling windows are separate variants rather than a day count because they answer
/// different questions and read from different places: a calendar month or year is served by the
/// monthly rollup tables, while a rolling window has to scan the events themselves.
sealed class SmartPeriod {
  const SmartPeriod();

  /// The `kind` this variant carries on the wire.
  String get kind;

  static SmartPeriod fromJson(Map<String, Object?> json) {
    switch (json['kind']) {
      case 'month':
        return SmartPeriodMonth.fromJson(json);
      case 'year':
        return SmartPeriodYear.fromJson(json);
      case 'rolling':
        return SmartPeriodRolling.fromJson(json);
      default:
        throw FormatException('Unknown SmartPeriod kind: ${json['kind']}');
    }
  }

  Map<String, Object?> toJson();
}

