/// A smart playlist summary.
class SmartPlaylist {
  const SmartPlaylist({
    required this.createdAt,
    required this.id,
    required this.name,
    required this.rules,
    this.autoCoverUrls,
    this.coverUrl,
    this.refreshIntervalMinutes,
    this.refreshOnComplete,
    this.refreshedAt,
    this.trackCount,
  });

  final int createdAt;
  final String id;
  final String name;
  final SmartRules rules;

  /// Up to 4 distinct album covers from the current snapshot, for an auto mosaic when no
  /// `cover_url` is set. Follows the rules, so it re-shuffles as the playlist does.
  final List<String>? autoCoverUrls;

  /// User-set cover, if any. Takes precedence over `auto_cover_urls`.
  ///
  /// Deliberately the same pair of fields a regular [`crate::catalog::Playlist`] carries, rather
  /// than the icon slug this used to be: a smart playlist is a playlist, and having one kind wear
  /// a picture and the other a glyph made them read as different species in the same sidebar.
  final String? coverUrl;

  /// Minutes between automatic refreshes; [`SMART_REFRESH_NEVER`] (`0`) = manual only.
  final int? refreshIntervalMinutes;

  /// Re-resolve the rules once the playlist has been played to the end, on top of any timed
  /// schedule.
  ///
  /// The point is a list that renews itself as you finish it rather than on a clock you have to
  /// guess at: "on repeat this month" is most useful the moment you have heard all of it. It is
  /// the CLIENT that reports this, because only the client knows a queue ran out, and only the
  /// queue knows which playlist it came from.
  final bool? refreshOnComplete;
  final int? refreshedAt;

  /// Tracks in the current snapshot, without hydrating them.
  final int? trackCount;

  factory SmartPlaylist.fromJson(Map<String, Object?> json) => SmartPlaylist(
    createdAt: asInt(json['created_at']),
    id: asString(json['id']),
    name: asString(json['name']),
    rules: SmartRules.fromJson(asObject(json['rules'])),
    autoCoverUrls: asListOrNull(
      json['auto_cover_urls'],
    )?.map((e) => asString(e)).toList(),
    coverUrl: asStringOrNull(json['cover_url']),
    refreshIntervalMinutes: asIntOrNull(json['refresh_interval_minutes']),
    refreshOnComplete: asBoolOrNull(json['refresh_on_complete']),
    refreshedAt: asIntOrNull(json['refreshed_at']),
    trackCount: asIntOrNull(json['track_count']),
  );

  Map<String, Object?> toJson() => {
    'created_at': createdAt,
    'id': id,
    'name': name,
    'rules': rules.toJson(),
    if (autoCoverUrls != null) 'auto_cover_urls': autoCoverUrls,
    if (coverUrl != null) 'cover_url': coverUrl,
    if (refreshIntervalMinutes != null)
      'refresh_interval_minutes': refreshIntervalMinutes,
    if (refreshOnComplete != null) 'refresh_on_complete': refreshOnComplete,
    if (refreshedAt != null) 'refreshed_at': refreshedAt,
    if (trackCount != null) 'track_count': trackCount,
  };
}

