/// Sort order for the resolved tracks.
enum SmartSort {
  title('title'),
  plays('plays'),
  random('random'),
  myPlays('my_plays'),
  myPlaysInPeriod('my_plays_in_period'),
  addedAt('added_at'),
  lastPlayed('last_played'),
  releaseDate('release_date'),
  duration('duration');

  const SmartSort(this.wire);

  /// The string this value takes on the wire.
  final String wire;

  static SmartSort? tryFromWire(Object? value) {
    for (final v in values) {
      if (v.wire == value) return v;
    }
    return null;
  }

  /// Falls back to [title] for a value this build does not know,
  /// so a server that gains a variant does not crash an older client.
  static SmartSort fromWire(Object? value) => tryFromWire(value) ?? title;
}

/// Sort direction. `None` on [`SmartRules::sort_dir`] means each sort's natural direction: A-Z for
/// title, largest or most recent first for everything else.
enum SmartSortDir {
