  /// Stateless by construction: it encodes the day and an offset, so `/more` rebuilds the same
  /// weave rather than reading a server-side session, and a retried request is idempotent.
  final String? nextCursor;

  factory Station.fromJson(Map<String, Object?> json) => Station(
    flavour: StationFlavour.fromWire(json['flavour']),
    kind: StationKind.fromWire(json['kind']),
    seedId: asString(json['seed_id']),
    seedName: asString(json['seed_name']),
    subtitle: asString(json['subtitle']),
    title: asString(json['title']),
    tracks: asList(
      json['tracks'],
    ).map((e) => BrowseTrack.fromJson(asObject(e))).toList(),
    imageUrl: asStringOrNull(json['image_url']),
    nextCursor: asStringOrNull(json['next_cursor']),
  );

  Map<String, Object?> toJson() => {
    'flavour': flavour.wire,
    'kind': kind.wire,
    'seed_id': seedId,
    'seed_name': seedName,
    'subtitle': subtitle,
    'title': title,
    'tracks': tracks.map((e) => e.toJson()).toList(),
    if (imageUrl != null) 'image_url': imageUrl,
    if (nextCursor != null) 'next_cursor': nextCursor,
  };
}

/// Which way a station faces.
///
/// **Not a label on the same list.** `Radio` points outward: it weights novelty, admits tracks the
/// listener has never played, and is endless. `Mix` points inward: it draws only from artists the
/// listener already plays plus their liked tracks, and is finite and stable for the day. The two are
/// the same machinery with the affinity term's SIGN flipped, which is the whole distinction.
enum StationFlavour {
  radio('radio'),
  mix('mix');

  const StationFlavour(this.wire);

  /// The string this value takes on the wire.
  final String wire;

  static StationFlavour? tryFromWire(Object? value) {
    for (final v in values) {
      if (v.wire == value) return v;
    }
    return null;
  }

  /// Falls back to [radio] for a value this build does not know,
  /// so a server that gains a variant does not crash an older client.
  static StationFlavour fromWire(Object? value) => tryFromWire(value) ?? radio;
}

/// What a station was seeded from. A genre seed is a slug, not an id — see [`Station::seed_id`].
enum StationKind {
  artist('artist'),
  track('track'),
  album('album'),
  genre('genre'),
  playlist('playlist');

  const StationKind(this.wire);

