/// One track in a catalog sync push. Carries everything the Hub needs to materialize canonical
/// artist/album/track rows and to associate the track with the originating library.
class SyncTrack {
  const SyncTrack({
    required this.artist,
    required this.artistNormalized,
    required this.contentHash,
    required this.durationMs,
    required this.title,
    required this.trackRef,
    this.advisory,
    this.album,
    this.albumArtist,
    this.albumNormalized,
    this.artistMbid,
    this.coverHash,
    this.discNo,
    this.edition,
    this.genre,
    this.isrc,
    this.recordingMbid,
    this.releaseMbid,
    this.trackNo,
    this.year,
  });

  final String artist;
  final String artistNormalized;

  /// SHA-256 of the file bytes, the Hub's per-library track identity key.
  final String contentHash;
  final int durationMs;
  final String title;

  /// The library's own track id, used by the player to build the stream URL.
  final String trackRef;

  /// Content advisory from the file's iTunes/ID3 rating tag: `"explicit"` or `"clean"`; `None` when
  /// unrated. Drives the EXPLICIT badge.
  final String? advisory;
  final String? album;
  final String? albumArtist;
  final String? albumNormalized;

  /// MusicBrainz id of the PRIMARY credited artist, from the file's `MusicBrainz Artist Id` tag.
  ///
  /// Artist identity used to cross this wire as name strings alone, so the Hub could only match on
  /// a name — and a name is not an identity. An album tagged with an artist's former name
  /// normalizes to something the current row does not equal, so ingest missed it and minted a
  /// duplicate; two different artists sharing a name collided the other way. The library had this
  /// id all along (`artists.mbid`, from `metadata.rs`) and already ships it over a DIFFERENT wire
  /// (`UpgradeProposal.artist_mbid`), so the omission here was a gap, not a data limitation.
  ///
  /// Optional because plenty of files carry no MusicBrainz tags at all; when it is absent the Hub
  /// falls back to the name matching it has always done.
  final String? artistMbid;

  /// SHA-256 of the embedded cover art, if any. Bytes are uploaded separately (see
  /// [`CatalogSyncResponse::missing_covers`]).
  final String? coverHash;
  final int? discNo;

  /// Edition qualifier ("Deluxe", "Special Edition", …) when this track comes from a deluxe/special
  /// edition that folds into the base album. `None` for the standard edition.
  final String? edition;
  final String? genre;
  final String? isrc;
  final String? recordingMbid;
  final String? releaseMbid;
  final int? trackNo;
  final int? year;

  factory SyncTrack.fromJson(Map<String, Object?> json) => SyncTrack(
    artist: asString(json['artist']),
    artistNormalized: asString(json['artist_normalized']),
    contentHash: asString(json['content_hash']),
    durationMs: asInt(json['duration_ms']),
    title: asString(json['title']),
    trackRef: asString(json['track_ref']),
    advisory: asStringOrNull(json['advisory']),
    album: asStringOrNull(json['album']),
    albumArtist: asStringOrNull(json['album_artist']),
    albumNormalized: asStringOrNull(json['album_normalized']),
    artistMbid: asStringOrNull(json['artist_mbid']),
    coverHash: asStringOrNull(json['cover_hash']),
    discNo: asIntOrNull(json['disc_no']),
    edition: asStringOrNull(json['edition']),
    genre: asStringOrNull(json['genre']),
    isrc: asStringOrNull(json['isrc']),
    recordingMbid: asStringOrNull(json['recording_mbid']),
    releaseMbid: asStringOrNull(json['release_mbid']),
    trackNo: asIntOrNull(json['track_no']),
    year: asIntOrNull(json['year']),
  );

  Map<String, Object?> toJson() => {
    'artist': artist,
    'artist_normalized': artistNormalized,
    'content_hash': contentHash,
    'duration_ms': durationMs,
    'title': title,
    'track_ref': trackRef,
    if (advisory != null) 'advisory': advisory,
    if (album != null) 'album': album,
    if (albumArtist != null) 'album_artist': albumArtist,
    if (albumNormalized != null) 'album_normalized': albumNormalized,
    if (artistMbid != null) 'artist_mbid': artistMbid,
    if (coverHash != null) 'cover_hash': coverHash,
    if (discNo != null) 'disc_no': discNo,
    if (edition != null) 'edition': edition,
    if (genre != null) 'genre': genre,
    if (isrc != null) 'isrc': isrc,
    if (recordingMbid != null) 'recording_mbid': recordingMbid,
    if (releaseMbid != null) 'release_mbid': releaseMbid,
    if (trackNo != null) 'track_no': trackNo,
    if (year != null) 'year': year,
  };
}

/// The paid deep-dive behind a compatibility score: what two listeners share, when they both
/// listen, and what they found at the same time. Every figure is bounded by each side's OWN
/// retention window — a paid viewer buys no reach into a free friend's hidden history.
class TasteSummary {
  const TasteSummary({
    required this.decades,
    required this.discoveredTogether,
    required this.eraOverlap,
    required this.hours,
    required this.sharedAlbums,
    required this.sharedGenres,
    required this.sharedTracks,
    required this.timeOverlap,
  });

  /// Album-release decades, one entry per decade on a continuous axis from the earliest decade
  /// either side has played through the latest.
  final List<DecadeSplit> decades;

  /// Artists whose first listen (week-grained) happened in the same week for both sides, with at
  /// least 5 plays each, strongest shared interest first, top 5.
  final List<DiscoveredTogether> discoveredTogether;

  /// Histogram intersection (0.0 to 1.0) of the two decade distributions: 1.0 means the same
  /// era shares, 0.0 means no overlap at all. 0.0 when either side has no dated plays.
  final double eraOverlap;

  /// Plays by local hour of day over the trailing 90 days, exactly 24 entries (index = hour).
  /// Each side's hours are measured in their own timezone — the comparison is "when in your day
  /// do you each listen", not "are you awake at the same instant".
  final List<HourSplit> hours;

  /// Albums both have played, ranked by the smaller of the two play counts (`plays` carries that
  /// shared strength), top 10.
  final List<TopItem> sharedAlbums;

  /// Album genres both have played. `id` is a stable hash of the genre name (genres aren't
  /// catalog entities) and `image_url` is always absent.
  final List<TopItem> sharedGenres;

  /// Tracks both have played, ranked and capped like `shared_albums`.
  final List<TopItem> sharedTracks;

  /// Histogram intersection (0.0 to 1.0) of the two hour-of-day distributions.
  final double timeOverlap;

  factory TasteSummary.fromJson(Map<String, Object?> json) => TasteSummary(
    decades: asList(
      json['decades'],
    ).map((e) => DecadeSplit.fromJson(asObject(e))).toList(),
    discoveredTogether: asList(
      json['discovered_together'],
    ).map((e) => DiscoveredTogether.fromJson(asObject(e))).toList(),
    eraOverlap: asDouble(json['era_overlap']),
    hours: asList(
      json['hours'],
    ).map((e) => HourSplit.fromJson(asObject(e))).toList(),
    sharedAlbums: asList(
      json['shared_albums'],
    ).map((e) => TopItem.fromJson(asObject(e))).toList(),
    sharedGenres: asList(
      json['shared_genres'],
    ).map((e) => TopItem.fromJson(asObject(e))).toList(),
    sharedTracks: asList(
      json['shared_tracks'],
    ).map((e) => TopItem.fromJson(asObject(e))).toList(),
    timeOverlap: asDouble(json['time_overlap']),
  );

  Map<String, Object?> toJson() => {
    'decades': decades.map((e) => e.toJson()).toList(),
    'discovered_together': discoveredTogether.map((e) => e.toJson()).toList(),
    'era_overlap': eraOverlap,
    'hours': hours.map((e) => e.toJson()).toList(),
    'shared_albums': sharedAlbums.map((e) => e.toJson()).toList(),
    'shared_genres': sharedGenres.map((e) => e.toJson()).toList(),
    'shared_tracks': sharedTracks.map((e) => e.toJson()).toList(),
    'time_overlap': timeOverlap,
  };
}

/// One bucket in a time series of listening activity.
class TimeBucket {
  const TimeBucket({
    required this.msPlayed,
    required this.plays,
    required this.start,
  });

