/// Layered identity for a recording, from strongest to weakest. Lets the same song match across
/// different files/encodings during own-copy lookup in DJ rooms.
class TrackFingerprint {
  const TrackFingerprint({
    required this.artistNorm,
    required this.contentHash,
    required this.durationMs,
    required this.titleNorm,
    this.acoustid,
    this.albumNorm,
    this.recordingMbid,
  });

  /// Normalized metadata for the fuzzy fallback tuple.
  final String artistNorm;

  /// SHA-256 of the raw file bytes (hex). Used for exact-file matching and a bit-perfect integrity check.
  final String contentHash;
  final int durationMs;
  final String titleNorm;

  /// AcoustID. A robust acoustic fingerprint that survives re-encoding. Preferred match.
  final String? acoustid;
  final String? albumNorm;

  /// MusicBrainz Recording ID.
  final String? recordingMbid;

  factory TrackFingerprint.fromJson(Map<String, Object?> json) =>
      TrackFingerprint(
        artistNorm: asString(json['artist_norm']),
        contentHash: asString(json['content_hash']),
        durationMs: asInt(json['duration_ms']),
        titleNorm: asString(json['title_norm']),
        acoustid: asStringOrNull(json['acoustid']),
        albumNorm: asStringOrNull(json['album_norm']),
        recordingMbid: asStringOrNull(json['recording_mbid']),
      );

  Map<String, Object?> toJson() => {
    'artist_norm': artistNorm,
    'content_hash': contentHash,
    'duration_ms': durationMs,
    'title_norm': titleNorm,
    if (acoustid != null) 'acoustid': acoustid,
    if (albumNorm != null) 'album_norm': albumNorm,
    if (recordingMbid != null) 'recording_mbid': recordingMbid,
  };
}

