/// One marker stripped from a title.
///
/// Ordered by how much it changes the recording: the first few are genuinely different performances
/// and the last few describe the release a track was on. That ordering is what the client renders
/// in, so the badge that matters most is the one nearest the title.
enum TrackVariant {
  live('live'),
  acoustic('acoustic'),
  instrumental('instrumental'),
  remix('remix'),
  demo('demo'),
  cover('cover'),
  karaoke('karaoke'),
  extended('extended'),
  radioEdit('radio_edit'),
  singleVersion('single_version'),
  remaster('remaster'),
  bonus('bonus'),
  deluxe('deluxe');

  const TrackVariant(this.wire);

  /// The string this value takes on the wire.
  final String wire;

  static TrackVariant? tryFromWire(Object? value) {
    for (final v in values) {
      if (v.wire == value) return v;
    }
    return null;
  }

  /// Falls back to [live] for a value this build does not know,
  /// so a server that gains a variant does not crash an older client.
  static TrackVariant fromWire(Object? value) => tryFromWire(value) ?? live;
}

