/// Per-user application preferences. Every field has a default so older/partial blobs still parse.
class UserSettings {
  const UserSettings({
    this.accent,
    this.accentMode,
    this.accentPalette,
    this.accentSpeed,
    this.autoplay,
    this.crossfadeSeconds,
    this.defaultSurface,
    this.emailNotifications,
    this.eq,
    this.eqPresets,
    this.followedArtistsVisibility,
    this.followersVisibility,
    this.followingVisibility,
    this.locale,
    this.nameAccent,
    this.normalizeVolume,
    this.openToFollows,
    this.playlistsVisibility,
    this.preloadCount,
    this.profileVisibility,
    this.scrobble,
    this.scrobblePrivacy,
    this.showProfileAccents,
    this.streamingQuality,
    this.timezone,
  });

  /// Accent preset name, hue-ordered: `crimson`, `ember`, `amber`, `lime`, `green`, `teal`,
  /// `blue`, `indigo`, `purple`, `magenta`, `pink`, or `default` — which is the default, and means
  /// "follow this deployment's accent" (`InstanceInfo::accent`) rather than naming a colour. An
  /// unrecognized value is used verbatim as a CSS colour.
  final String? accent;

  /// How the accent behaves over time. `Static` (the default) uses `accent` as-is; every other
  /// mode needs [`crate::billing::Feature::DynamicAccent`], and the Hub serves `Static` to an
  /// account that no longer has it rather than rewriting the stored choice — so the look comes
  /// back intact if they resubscribe.
  final AccentMode? accentMode;

  /// The colours a non-static mode cycles or blends between, and the fallback for `Artwork` when a
  /// track has no cover. Two to six CSS colours; ignored when `accent_mode` is `Static`.
  final List<String>? accentPalette;

  /// How fast the moving accent modes move. Ignored by [`AccentMode::Static`],
  /// [`AccentMode::Gradient`] and [`AccentMode::Artwork`], none of which move on a timer.
  final AccentSpeed? accentSpeed;
  final bool? autoplay;

  /// Overlap-crossfade duration in seconds between consecutive tracks (`0` = off, the default, so
  /// tracks change with the normal short handoff). Clamped to `0..=12` client-side; streaming
  /// sources only (a crossfade needs the Web Audio graph). The frontend drives the dual-deck engine.
  final int? crossfadeSeconds;

  /// Where the app opens by default: `app` or `library`.
  final String? defaultSurface;

  /// Whether to receive transactional email notifications (e.g. a friend request). Default on.
  final bool? emailNotifications;

  /// Parametric equalizer state.
  final EqConfig? eq;

  /// The user's saved custom EQ presets.
  final List<EqPreset>? eqPresets;

  /// Who may see the artists this user follows.
  final Audience? followedArtistsVisibility;

  /// Who may see the list of accounts following this user.
  final Audience? followersVisibility;

  /// Who may see the list of accounts this user follows.
  final Audience? followingVisibility;

  /// Preferred UI + email language as a locale code (e.g. `en`, `es`). Empty = follow the
  /// request's `Accept-Language`. Drives server-originated text (errors, emails) and the client
  /// UI; the frontend also mirrors it into the `chordia_locale` cookie so SSR's first paint agrees.
  final String? locale;

  /// Paint this user's display name in their accent wherever it appears. Requires
  /// [`crate::billing::Feature::NameAccent`]; on by default so the perk is visible the moment it
  /// is bought rather than needing to be found.
  final bool? nameAccent;
  final bool? normalizeVolume;

  /// Whether other users may follow this account without asking. Default on.
  final bool? openToFollows;

  /// Who may see this user's public playlists on their profile. Defaults to `Private`: a
  /// playlist's own `PlaylistVisibility` opts it in, this only widens the *shelf*.
  final Audience? playlistsVisibility;

  /// How many upcoming queue tracks to prefetch in the background for seamless, gap-free
  /// playback. `0` disables prefetch; clamped client-side. Prefetched audio outside the window is
  /// evicted as the queue advances.
  final int? preloadCount;

  /// Who may see the user's profile page at all.
  ///
  /// Defaults to `Private`. This is the front door — every other surface here is only reachable
  /// once it has let the viewer through — so it is the one that has to be opened deliberately.
  final Audience? profileVisibility;

  /// Whether listens are scrobbled to the Hub.
  final bool? scrobble;

  /// Who can see this user's listening activity in social insights.
  final ScrobblePrivacy? scrobblePrivacy;

  /// Whether OTHER people's profile accents apply while this user is viewing them. A viewer-side
  /// opt-out, not a subject-side one: nobody should be stuck with a page colour they find
  /// unreadable, and the person choosing the colour is not the person reading it.
  final bool? showProfileAccents;

  /// Listener-selected quality tier (the streaming ceiling). Serializes as `original`, `high`,
  /// `normal`, or `data_saver`.
  final QualityProfile? streamingQuality;

  /// IANA timezone used for calendar-based listening insights. Empty = follow the client.
  final String? timezone;

  factory UserSettings.fromJson(Map<String, Object?> json) => UserSettings(
    accent: asStringOrNull(json['accent']),
    accentMode: AccentMode.tryFromWire(json['accent_mode']),
    accentPalette: asListOrNull(
      json['accent_palette'],
    )?.map((e) => asString(e)).toList(),
    accentSpeed: AccentSpeed.tryFromWire(json['accent_speed']),
    autoplay: asBoolOrNull(json['autoplay']),
    crossfadeSeconds: asIntOrNull(json['crossfade_seconds']),
    defaultSurface: asStringOrNull(json['default_surface']),
    emailNotifications: asBoolOrNull(json['email_notifications']),
    eq: json['eq'] == null ? null : EqConfig.fromJson(asObject(json['eq'])),
    eqPresets: asListOrNull(
      json['eq_presets'],
    )?.map((e) => EqPreset.fromJson(asObject(e))).toList(),
    followedArtistsVisibility: Audience.tryFromWire(
      json['followed_artists_visibility'],
    ),
    followersVisibility: Audience.tryFromWire(json['followers_visibility']),
    followingVisibility: Audience.tryFromWire(json['following_visibility']),
    locale: asStringOrNull(json['locale']),
    nameAccent: asBoolOrNull(json['name_accent']),
    normalizeVolume: asBoolOrNull(json['normalize_volume']),
    openToFollows: asBoolOrNull(json['open_to_follows']),
    playlistsVisibility: Audience.tryFromWire(json['playlists_visibility']),
    preloadCount: asIntOrNull(json['preload_count']),
    profileVisibility: Audience.tryFromWire(json['profile_visibility']),
    scrobble: asBoolOrNull(json['scrobble']),
    scrobblePrivacy: ScrobblePrivacy.tryFromWire(json['scrobble_privacy']),
    showProfileAccents: asBoolOrNull(json['show_profile_accents']),
    streamingQuality: QualityProfile.tryFromWire(json['streaming_quality']),
    timezone: asStringOrNull(json['timezone']),
  );

  Map<String, Object?> toJson() => {
    if (accent != null) 'accent': accent,
    if (accentMode != null) 'accent_mode': accentMode!.wire,
    if (accentPalette != null) 'accent_palette': accentPalette,
    if (accentSpeed != null) 'accent_speed': accentSpeed!.wire,
    if (autoplay != null) 'autoplay': autoplay,
    if (crossfadeSeconds != null) 'crossfade_seconds': crossfadeSeconds,
    if (defaultSurface != null) 'default_surface': defaultSurface,
    if (emailNotifications != null) 'email_notifications': emailNotifications,
    if (eq != null) 'eq': eq!.toJson(),
    if (eqPresets != null)
      'eq_presets': eqPresets!.map((e) => e.toJson()).toList(),
    if (followedArtistsVisibility != null)
      'followed_artists_visibility': followedArtistsVisibility!.wire,
    if (followersVisibility != null)
      'followers_visibility': followersVisibility!.wire,
    if (followingVisibility != null)
      'following_visibility': followingVisibility!.wire,
    if (locale != null) 'locale': locale,
    if (nameAccent != null) 'name_accent': nameAccent,
    if (normalizeVolume != null) 'normalize_volume': normalizeVolume,
    if (openToFollows != null) 'open_to_follows': openToFollows,
    if (playlistsVisibility != null)
      'playlists_visibility': playlistsVisibility!.wire,
    if (preloadCount != null) 'preload_count': preloadCount,
    if (profileVisibility != null)
      'profile_visibility': profileVisibility!.wire,
    if (scrobble != null) 'scrobble': scrobble,
    if (scrobblePrivacy != null) 'scrobble_privacy': scrobblePrivacy!.wire,
    if (showProfileAccents != null) 'show_profile_accents': showProfileAccents,
    if (streamingQuality != null) 'streaming_quality': streamingQuality!.wire,
    if (timezone != null) 'timezone': timezone,
  };
}

/// A listening-insights report for a user over a period.
///
/// Computed live from the partitioned `listening_events` fact table, scoped to one user over a
/// bounded window. (This previously claimed to be served from precomputed rollups; it never was —
/// the fixed-grain rollups cannot answer an arbitrary rolling window precisely.)
class WrappedReport {
  const WrappedReport({
    required this.decades,
    required this.fingerprint,
    required this.genreTrend,
    required this.period,
    required this.timezone,
    required this.topAlbums,
    required this.topArtists,
    required this.topGenres,
    required this.topTracks,
    required this.totalMsPlayed,
    required this.totalMsPlayedCompared,
    required this.totalPlays,
    required this.totalPlaysCompared,
    required this.undatedReleaseShare,
    required this.uniqueAlbums,
    required this.uniqueAlbumsCompared,
    required this.uniqueArtists,
    required this.uniqueArtistsCompared,
    required this.uniqueTracks,
    required this.uniqueTracksCompared,
    required this.userId,
    required this.windowEnd,
    required this.windowStart,
  });

  /// Continuous decade axis from the earliest dated album played through the current decade.
  final List<DecadeBucket> decades;
  final FingerprintReport fingerprint;

  /// Album genres over the same local-calendar buckets used by listening charts.
  final GenreTrend genreTrend;
  final Period period;

  /// IANA timezone used to align the current and preceding windows to local midnights.
  final String timezone;
  final List<TopItem> topAlbums;
  final List<TopItem> topArtists;

  /// Top genres by play count. `id` is a stable hash of the genre name (genres aren't catalog
  /// entities), and `image_url` is always `None`.
  final List<TopItem> topGenres;
  final List<TopItem> topTracks;
  final int totalMsPlayed;
  final Compared totalMsPlayedCompared;
  final int totalPlays;
  final Compared totalPlaysCompared;

  /// Share of plays whose album release date cannot be resolved (`0.0..=1.0`).
  final double undatedReleaseShare;
  final int uniqueAlbums;
  final Compared uniqueAlbumsCompared;
  final int uniqueArtists;
  final Compared uniqueArtistsCompared;
  final int uniqueTracks;
  final Compared uniqueTracksCompared;
  final String userId;

  /// Exclusive end of the window (epoch millis).
  final int windowEnd;

  /// Inclusive start of the window (epoch millis).
  final int windowStart;

  factory WrappedReport.fromJson(Map<String, Object?> json) => WrappedReport(
    decades: asList(
      json['decades'],
    ).map((e) => DecadeBucket.fromJson(asObject(e))).toList(),
    fingerprint: FingerprintReport.fromJson(asObject(json['fingerprint'])),
    genreTrend: GenreTrend.fromJson(asObject(json['genre_trend'])),
    period: Period.fromWire(json['period']),
    timezone: asString(json['timezone']),
    topAlbums: asList(
      json['top_albums'],
    ).map((e) => TopItem.fromJson(asObject(e))).toList(),
    topArtists: asList(
      json['top_artists'],
    ).map((e) => TopItem.fromJson(asObject(e))).toList(),
    topGenres: asList(
      json['top_genres'],
    ).map((e) => TopItem.fromJson(asObject(e))).toList(),
    topTracks: asList(
      json['top_tracks'],
    ).map((e) => TopItem.fromJson(asObject(e))).toList(),
    totalMsPlayed: asInt(json['total_ms_played']),
    totalMsPlayedCompared: Compared.fromJson(
      asObject(json['total_ms_played_compared']),
    ),
    totalPlays: asInt(json['total_plays']),
    totalPlaysCompared: Compared.fromJson(
      asObject(json['total_plays_compared']),
    ),
    undatedReleaseShare: asDouble(json['undated_release_share']),
    uniqueAlbums: asInt(json['unique_albums']),
    uniqueAlbumsCompared: Compared.fromJson(
      asObject(json['unique_albums_compared']),
    ),
    uniqueArtists: asInt(json['unique_artists']),
    uniqueArtistsCompared: Compared.fromJson(
      asObject(json['unique_artists_compared']),
    ),
    uniqueTracks: asInt(json['unique_tracks']),
    uniqueTracksCompared: Compared.fromJson(
      asObject(json['unique_tracks_compared']),
    ),
    userId: asString(json['user_id']),
    windowEnd: asInt(json['window_end']),
    windowStart: asInt(json['window_start']),
  );

  Map<String, Object?> toJson() => {
    'decades': decades.map((e) => e.toJson()).toList(),
    'fingerprint': fingerprint.toJson(),
    'genre_trend': genreTrend.toJson(),
    'period': period.wire,
    'timezone': timezone,
    'top_albums': topAlbums.map((e) => e.toJson()).toList(),
    'top_artists': topArtists.map((e) => e.toJson()).toList(),
    'top_genres': topGenres.map((e) => e.toJson()).toList(),
    'top_tracks': topTracks.map((e) => e.toJson()).toList(),
    'total_ms_played': totalMsPlayed,
    'total_ms_played_compared': totalMsPlayedCompared.toJson(),
    'total_plays': totalPlays,
    'total_plays_compared': totalPlaysCompared.toJson(),
    'undated_release_share': undatedReleaseShare,
    'unique_albums': uniqueAlbums,
    'unique_albums_compared': uniqueAlbumsCompared.toJson(),
    'unique_artists': uniqueArtists,
    'unique_artists_compared': uniqueArtistsCompared.toJson(),
    'unique_tracks': uniqueTracks,
    'unique_tracks_compared': uniqueTracksCompared.toJson(),
    'user_id': userId,
    'window_end': windowEnd,
    'window_start': windowStart,
  };
}
